parameters.jsCode:
const execution = $input.first().json;
const config = $('Alert Config').first().json;

const failedNode = execution.execution?.lastNodeExecuted || execution.lastNodeExecuted || 'Unknown node';
const workflowName = execution.workflow?.name || 'YouTube Shorts Automation';
const workflowId = execution.workflow?.id || '';
const errorMessage = execution.execution?.error?.message || execution.error?.message || 'Unknown error';
const errorStack = execution.execution?.error?.stack || execution.error?.stack || '';
const mode = execution.execution?.mode || execution.mode || 'unknown';
const timestamp = new Date().toISOString();

return [{
  json: {
    alertWebhookUrl: config.alertWebhookUrl,
    severity: 'error',
    service: 'youtube-shorts-automation',
    timestamp,
    workflowName,
    workflowId,
    failedNode,
    executionMode: mode,
    errorMessage,
    errorStack,
    slackText: `🚨 *YouTube Shorts Automation Failed*\n• Workflow: ${workflowName}\n• Node: ${failedNode}\n• Error: ${errorMessage}\n• Time: ${timestamp}`,
    discordContent: `🚨 **YouTube Shorts Automation Failed**\nWorkflow: ${workflowName}\nNode: ${failedNode}\nError: ${errorMessage}\nTime: ${timestamp}`
  }
}];

